Theorem visit_int64_nested_ok : forall (v : Z) (LBo : list (Z * Z)) (FF LK : list fframe) (cr : credit) (A : list (Z * Z)) (sp r V S2 kx bx : Z) (g : eghost) (c0 : ectx) (r0 : estate),
  g_es g = c0 :: r0 ->
  PMSA.cps_asan L ar HI PMESA.PC_VISIT_INT64_xboth r sp (PMESA.VIS_SCRA 12800) (LBo ++ g_lbv g) FF LK cr A PMESA.VIS_D
    (fun R M => PMSA.a0 R V /\ (PMSA.a1 R v /\ 0 <= v < 2 ^ 64) /\ sp mod 32 = 0 /\ PMSA.stksh ar M sp (PMESA.VIS_SCRA 12800) /\ PMESA.enc_invA L IC EC M V S2 g /\ ev_guard (g_es g) EvI64 /\
                PMESA.eroomA CL g EvI64 /\ PMLA.img_ro IC M /\ PMESA.lits_ok L IC M /\ PMESA.ecreditA L CL cr g kx bx /\
                PMSA.fobj M FF V ENC_SIZE /\ PMSA.fobj M FF S2 24 /\ PMLA.apart V ENC_SIZE S2 24)
    (fun R M R' M' LB' cr' LBk W => exists (g' : eghost) (pay : Z),
        PMSA.a0 R' 1 /\ PMESA.enc_invA L IC EC M' V S2 g' /\ g_es g' = estep (g_es g) EvI64 /\ pay_ok EvI64 pay /\ g_len g' = g_len g + ev_ind (g_es g) EvI64 + pay /\
